// Toasts for OpenAdmin pages: showToast(message, type, isPermanent, reportLink, details)
// message and details are plain text (never parsed as HTML). details, when given, sits in a collapsed
// "Show details" box with a Copy button, for raw command output such as a podman error.
let activeToasts = [];

function removeToast(el) {
    if (!el || !el.parentElement) return;
    activeToasts = activeToasts.filter((t) => {
        if (t.element === el) { el.remove(); return false; }
        return true;
    });
}

const TOAST_ICONS = {
    success: { color: 'text-emerald-500 dark:text-emerald-500', title: 'Success', svg: '<svg class="remixicon w-5 h-5" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 17.5228 6.47715 22 12 22ZM17.4571 9.45711L11 15.9142L6.79289 11.7071L8.20711 10.2929L11 13.0858L16.0429 8.04289L17.4571 9.45711Z"/></svg>' },
    error: { color: 'text-red-500 dark:text-red-500', title: 'Error', svg: '<svg class="remixicon w-5 h-5" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M12 22C6.47715 22 2 17.5228 2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22ZM12 10.5858L9.17157 7.75736L7.75736 9.17157L10.5858 12L7.75736 14.8284L9.17157 16.2426L12 13.4142L14.8284 16.2426L16.2426 14.8284L13.4142 12L16.2426 9.17157L14.8284 7.75736L12 10.5858Z"/></svg>' },
    info: { color: 'text-blue-500 dark:text-blue-500', title: 'Info', svg: '<svg class="remixicon w-5 h-5" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24"><path d="M12 22C6.47715 22 2 17.5228 2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22ZM11 11V17H13V11H11ZM11 7V9H13V7H11Z"></path></svg>' },
    warning: { color: 'text-yellow-500 dark:text-yellow-500', title: 'Warning', svg: '<svg class="remixicon w-5 h-5" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M12 22C6.47715 22 2 17.5228 2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22ZM11 15V17H13V15H11ZM11 7V13H13V7H11Z"/></svg>' },
    loading: { color: 'text-blue-500 dark:text-blue-500', title: 'Working', svg: '<svg class="w-5 h-5 animate-spin" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" stroke="currentColor" stroke-opacity=".25" stroke-width="3"></circle><path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" stroke-width="3" stroke-linecap="round"></path></svg>' },
};

// the details box isn't in the Tailwind build (that only scans templates), so its look lives here
(function () {
    const st = document.createElement('style');
    st.textContent = `
.op-toast-text{min-width:0;flex:1 1 auto}
.op-toast-msg{overflow-wrap:anywhere;white-space:pre-line}
.op-toast-details{margin-top:6px;font-size:12px}
.op-toast-details summary{cursor:pointer;color:inherit;opacity:.85;user-select:none}
.op-toast-details summary:focus-visible{outline:2px solid #3b82f6;outline-offset:2px;border-radius:3px}
.op-toast-details pre{margin:6px 0 0;max-height:14rem;overflow:auto;padding:8px 10px;border-radius:6px;background:rgba(0,0,0,.05);font:12px/1.45 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}
html.dark .op-toast-details pre{background:rgba(255,255,255,.06)}
.op-toast-copy{margin-top:6px;display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:5px;border:1px solid rgba(0,0,0,.15);background:none;color:inherit;font:inherit;font-size:12px;cursor:pointer}
html.dark .op-toast-copy{border-color:rgba(255,255,255,.18)}
.op-toast-copy:hover{background:rgba(0,0,0,.05)}
html.dark .op-toast-copy:hover{background:rgba(255,255,255,.06)}`;
    (document.head || document.documentElement).appendChild(st);
})();

// the hidden textarea way, for plain http, old browsers and browsers that refuse the Clipboard API
function copyToastTextFallback(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    let ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    ta.remove();
    return ok ? Promise.resolve() : Promise.reject(new Error('copy'));
}

function copyToastText(text) {
    if (navigator.clipboard && window.isSecureContext) {
        return navigator.clipboard.writeText(text).catch(() => copyToastTextFallback(text));
    }
    return copyToastTextFallback(text);
}

function showToast(message, type, isPermanent = false, reportLink = false, details = '') {
    // errors and spinners stay until closed or replaced, an error has to be read before it goes
    isPermanent = isPermanent || type === 'error' || type === 'loading';
    const container = document.getElementById('toast-container');
    if (!container) { console.error('Toast container not found!'); return; }

    // a result replaces the spinner that was waiting for it
    if (type !== 'loading') {
        activeToasts = activeToasts.filter((t) => {
            if (t.type === 'loading') { t.element.remove(); return false; }
            return true;
        });
    }

    const cfg = TOAST_ICONS[type] || TOAST_ICONS.info;
    const el = document.createElement('div');
    el.className = 'flex h-fit min-h-16 overflow-hidden rounded-md border shadow-lg shadow-black/5 bg-white dark:bg-raised border-gray-200 dark:border-gray-800';
    el.setAttribute('role', 'alert');
    el.innerHTML = `<div class="flex flex-1 items-start gap-3 p-4 border-r border-gray-200 dark:border-gray-800" style="min-width:0"><span class="mt-0.5 shrink-0 ${cfg.color}">${cfg.svg}</span><div class="op-toast-text flex flex-col gap-1"><div class="text-sm font-semibold text-gray-900 dark:text-gray-50"></div><div class="op-toast-msg text-sm text-gray-600 dark:text-gray-400"></div></div></div><div class="flex flex-col shrink-0">${reportLink ? '<a target="_blank" rel="noopener" data-toast-report class="flex flex-1 items-center justify-center px-6 text-sm font-semibold transition-colors hover:bg-gray-50 hover:dark:bg-gray-900/30 active:bg-gray-100 active:dark:bg-gray-800 text-red-600 dark:text-red-500">Send Report</a><div class="h-px w-full bg-gray-200 dark:bg-gray-800"></div>' : ''}<button type="button" class="flex flex-1 items-center justify-center px-6 text-sm text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-900/30 active:bg-gray-100 h-full" aria-label="Close">Close</button></div>`;

    const text = el.querySelector('.op-toast-text');
    text.children[0].textContent = cfg.title;
    text.children[1].textContent = message == null ? '' : String(message);
    if (reportLink) el.querySelector('[data-toast-report]').setAttribute('href', reportLink);

    details = details == null ? '' : String(details).trim();
    if (details && details !== String(message).trim()) {
        const box = document.createElement('details');
        box.className = 'op-toast-details text-gray-600 dark:text-gray-400';
        const sum = document.createElement('summary');
        sum.textContent = 'Show details';
        const pre = document.createElement('pre');
        pre.textContent = details;
        const copy = document.createElement('button');
        copy.type = 'button';
        copy.className = 'op-toast-copy';
        copy.textContent = 'Copy';
        copy.addEventListener('click', () => {
            // the summary line and the raw output together, that's what a bug report needs
            copyToastText(String(message) + '\n\n' + details)
                .then(() => { copy.textContent = 'Copied'; setTimeout(() => { copy.textContent = 'Copy'; }, 2000); })
                .catch(() => { copy.textContent = 'Select the text above and copy it'; });
        });
        box.addEventListener('toggle', () => { sum.textContent = box.open ? 'Hide details' : 'Show details'; });
        box.append(sum, pre, copy);
        text.appendChild(box);
    }

    container.appendChild(el);
    activeToasts.push({ type, element: el });

    const close = el.querySelector('button[aria-label="Close"]');
    if (isPermanent) {
        close.addEventListener('click', () => removeToast(el));
    } else {
        const timer = setTimeout(() => removeToast(el), 5000);
        close.addEventListener('click', () => { clearTimeout(timer); removeToast(el); });
    }
}
